mapper.select:
SELECT 
FROM flash_sale
WHERE is_deleted = 0
  AND start_at <= #{now}
  AND end_at >= #{now}
ORDER BY end_at ASC, sale_id ASC

mapper.update:
UPDATE flash_sale
SET sale_stock = sale_stock - #{quantity},
    updated_at = NOW()
WHERE sale_id = #{saleId}
  AND sale_stock >= #{quantity}
  AND start_at <= #{now}
  AND end_at >= #{now}
  AND is_deleted = 0
